	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.record_Subscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Record_ : " + successValue.getRecord_Id());
							  if (successValue.getRecord_Id().equals(record_Id)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfRecord_List - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Record_ test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on record_ consumed")
					);
			subscriber.record_Subscribe( record_Id ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Record_ : " + successValue.getRecord_Id() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfRecord_List = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on record_ for record_Id consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Record_. 
	 */
	protected Record_ read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Record_" );

		Record_ entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Record_ with primary key" );
		msg.append( record_Id );
		
		Record_FetchOneSummary fetchOneSummary = new Record_FetchOneSummary( record_Id );

		try {
			entity = Record_Service.getRecord_Instance().getRecord_( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Record_ " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Record_.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Record_." );

		StringBuilder msg = new StringBuilder( "Failed to update a Record_ : " );        
		Record_ entity = read();
		UpdateRecord_Command command = generateUpdateCommand();
		command.setRecord_Id(entity.getRecord_Id());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Record_." );

			// for use later on...
			record_Id = entity.getRecord_Id();

			Record_Service proxy = Record_Service.getRecord_Instance();  

			proxy.updateRecord_( command ).get();

			LOGGER.info( "-- Successfully saved Record_ - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + record_Id + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Record_.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Record_." );

		Record_ entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Record_ with id " + record_Id );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Record_ with id " + record_Id );

			throw e;
		}

		try{
			Record_Service.getRecord_Instance().delete( new DeleteRecord_Command( entity.getRecord_Id() ) ).get();
			LOGGER.info( "-- Successfully deleted Record_ with id " + record_Id );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Record_ with id " + record_Id );

			throw e;
		}
	}

	/**
	 * get all Record_s.
	 */
	protected List<Record_> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Record_s:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Record_ : " );        
		List<Record_> collection  = new ArrayList<>();

		try {
			// call the static get method on the Record_Service
			collection = Record_Service.getRecord_Instance().getAllRecord_();
			assertNotNull( collection, "An Empty collection of Record_ was incorrectly returned.");
			
			// Now print out the values
			Record_ entity = null;            
			Iterator<Record_> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getRecord_Id(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

